// Une los fragmentos recuperados de Pinecone en un solo string de contexto.
const docs = $input.all();

const chunks = docs.map((item, i) => {
  const d = item.json.document || item.json;
  const texto = d.pageContent || d.text || d.content || '';
  return texto ? `[fragmento ${i + 1}] ${texto}` : '';
}).filter(Boolean);

const contexto_recuperado = chunks.length
  ? chunks.join('\n\n')
  : 'SIN CONTEXTO RECUPERADO';

// Datos originales enviados por el flujo principal (trigger en modo passthrough).
const src = $('Recibir del agente').first().json;

return [{
  json: {
    pregunta: src.pregunta || '',
    respuesta_agente: src.respuesta_agente || '',
    intento: Number(src.intento) || 1,
    arquitectura: src.arquitectura || 'B',
    contexto_recuperado
  }
}];

