// El Juez procesa UNA respuesta por ejecución.
const judgeRaw = $input.first().json.output;
if (!judgeRaw) {
  throw new Error('El Juez no devolvió ningún output.');
}

let v;
try {
  v = JSON.parse(String(judgeRaw).replace(/```json/gi, '').replace(/```/g, '').trim());
} catch (e) {
  throw new Error('El Juez no devolvió un JSON válido. Salida: ' + judgeRaw);
}

// Recuperamos los datos originales (el nodo del agente reemplaza el item).
const src = $('Armar contexto').first().json;
const intento = Number(src.intento) || 1;

// ── Contador de intentos: evita bucles infinitos de corrección ──
const MAX_CORRECCIONES = 2; // máximo 2 correcciones; luego se escala a un humano

let estado = String(v.estado || '').toUpperCase().trim();
const score = Number.isFinite(Number(v.score)) ? Number(v.score) : 0;
const errores = Array.isArray(v.errores) ? v.errores : [];
const justificacion = v.justificacion || '';

// Si el Juez pide CORREGIR pero ya agotamos las correcciones -> ESCALAR
if (estado === 'CORREGIR' && (intento - 1) >= MAX_CORRECCIONES) {
  estado = 'ESCALAR';
  errores.push('Se alcanzó el máximo de ' + MAX_CORRECCIONES + ' correcciones sin aprobar la respuesta.');
}

// Cualquier valor inesperado -> ESCALAR (fail-safe)
if (!['APROBADO', 'CORREGIR', 'ESCALAR'].includes(estado)) {
  estado = 'ESCALAR';
  errores.push('El Juez devolvió un estado no reconocido: ' + (v.estado == null ? 'null' : v.estado));
}

// Feedback para el agente (se usa sólo en la ruta CORREGIR del flujo principal).
const feedback =
  'Tu respuesta anterior fue RECHAZADA por el supervisor de calidad. ' +
  'Errores detectados: ' + (errores.length ? errores.join('; ') : 'ver rúbrica') + '. ' +
  'Generá una nueva versión corrigiendo exactamente esos puntos. ' +
  'No inventes datos que no estén en la base de conocimiento.';

return [{
  json: {
    pregunta: src.pregunta,
    respuesta_agente: src.respuesta_agente,
    contexto_recuperado: src.contexto_recuperado,
    arquitectura: src.arquitectura || 'B',
    intento,
    score,
    estado,
    errores,
    justificacion,
    feedback
  }
}];

